sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */

function evaluateProperty({
    api,
    helpers
}) {
    const {
        selectedType
    } = api.state;

    if (selectedType === 'one') {
        const {
            legal_name,
            identity_verification_types,
            domicile_country,
            email_id,
        } = api.state;

        if (
            !legal_name ||
            !identity_verification_types ||
            !domicile_country ||
            !email_id
        ) {
            return true;
        }
        return false;
    } else {
        const {
            legal_entity_name,
            registration_number,
            domicile_country1,
            authorized_reporter,
            email_id1
        } = api.state;


        if (!legal_entity_name || !registration_number || !domicile_country1 || !authorized_reporter || !email_id1) {
            return true;
        }
        return false;
    }
    return true;
}
